WITH flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, ROUND(SUM(humidity) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS humidity_per_dv_04, COUNT(*) AS row_count, MAX(temp_c) AS max_temp_c FROM sessionized GROUP BY hour_window HAVING max_temp_c >= 0 ORDER BY hour_window NULLS FIRST
